import java.util.*;

public class Main {
    enum Mode { CP, AP }

    static class ReplicatedStore {
        private final Mode mode;
        private final Map<String, String> primary = new HashMap<>();
        private final Map<String, String> replica = new HashMap<>();
        private boolean partitioned = false;

        ReplicatedStore(Mode mode) {
            this.mode = mode;
        }

        void setPartitioned(boolean value) {
            this.partitioned = value;
        }

        String write(String key, String value) {
            if (partitioned && mode == Mode.CP) {
                return "REJECTED: cannot confirm replica is caught up during partition";
            }
            primary.put(key, value);
            if (!partitioned) {
                replica.put(key, value);
            }
            return partitioned
                ? "ACCEPTED on primary only, replica now stale until partition heals"
                : "ACCEPTED and replicated";
        }

        String readFromReplica(String key) {
            if (partitioned && mode == Mode.CP) {
                return "REJECTED: replica cannot be trusted during partition";
            }
            return replica.getOrDefault(key, "no value");
        }
    }

    public static void main(String[] args) {
        ReplicatedStore cp = new ReplicatedStore(Mode.CP);
        ReplicatedStore ap = new ReplicatedStore(Mode.AP);

        cp.write("x", "3");
        ap.write("x", "3");

        cp.setPartitioned(true);
        ap.setPartitioned(true);

        System.out.println("CP write during partition: " + cp.write("x", "5"));
        System.out.println("CP read from replica during partition: " + cp.readFromReplica("x"));

        System.out.println("AP write during partition: " + ap.write("x", "5"));
        System.out.println("AP read from replica during partition: " + ap.readFromReplica("x"));
    }
}

