class Mode:
    CP = "CP"
    AP = "AP"


class ReplicatedStore:
    def __init__(self, mode):
        self.mode = mode
        self.primary = {}
        self.replica = {}
        self.partitioned = False

    def set_partitioned(self, value):
        self.partitioned = value

    def write(self, key, value):
        if self.partitioned and self.mode == Mode.CP:
            return "REJECTED: cannot confirm replica is caught up during partition"
        self.primary[key] = value
        if not self.partitioned:
            self.replica[key] = value
        if self.partitioned:
            return "ACCEPTED on primary only, replica now stale until partition heals"
        return "ACCEPTED and replicated"

    def read_from_replica(self, key):
        if self.partitioned and self.mode == Mode.CP:
            return "REJECTED: replica cannot be trusted during partition"
        return self.replica.get(key, "no value")


def main():
    cp = ReplicatedStore(Mode.CP)
    ap = ReplicatedStore(Mode.AP)

    cp.write("x", "3")
    ap.write("x", "3")

    cp.set_partitioned(True)
    ap.set_partitioned(True)

    print(f"CP write during partition: {cp.write('x', '5')}")
    print(f"CP read from replica during partition: {cp.read_from_replica('x')}")

    print(f"AP write during partition: {ap.write('x', '5')}")
    print(f"AP read from replica during partition: {ap.read_from_replica('x')}")


if __name__ == "__main__":
    main()

