#include <iostream>
#include <string>
#include <unordered_map>
using namespace std;

enum class Mode { CP, AP };

class ReplicatedStore {
public:
    ReplicatedStore(Mode m) : mode(m), partitioned(false) {}

    void setPartitioned(bool value) { partitioned = value; }

    string write(const string& key, const string& value) {
        if (partitioned && mode == Mode::CP) {
            return "REJECTED: cannot confirm replica is caught up during partition";
        }
        primary[key] = value;
        if (!partitioned) {
            replica[key] = value;
        }
        return partitioned
            ? "ACCEPTED on primary only, replica now stale until partition heals"
            : "ACCEPTED and replicated";
    }

    string readFromReplica(const string& key) {
        if (partitioned && mode == Mode::CP) {
            return "REJECTED: replica cannot be trusted during partition";
        }
        auto it = replica.find(key);
        return it == replica.end() ? "no value" : it->second;
    }

private:
    Mode mode;
    unordered_map<string, string> primary;
    unordered_map<string, string> replica;
    bool partitioned;
};

int main() {
    ReplicatedStore cp(Mode::CP);
    ReplicatedStore ap(Mode::AP);

    cp.write("x", "3");
    ap.write("x", "3");

    cp.setPartitioned(true);
    ap.setPartitioned(true);

    cout << "CP write during partition: " << cp.write("x", "5") << endl;
    cout << "CP read from replica during partition: " << cp.readFromReplica("x") << endl;

    cout << "AP write during partition: " << ap.write("x", "5") << endl;
    cout << "AP read from replica during partition: " << ap.readFromReplica("x") << endl;

    return 0;
}
